#define k_about_title						(  STRING_IDS::MENU_ABOUT_TITLE  ) 

#define STRINGS_ABOUT_BEGIN					( STRING_IDS::ABOUT_ABOUT_LINE_1 )
#define STRINGS_ABOUT_END					( STRING_IDS::ABOUT_ABOUT_LINE_END )

#define control_id_base						( 10 )

#define TEXT_CONTROLS_OFFSET_PER_SECOND		( 30.0f )

#define k_about_line_spacing				( 30 )
#define k_about_pos_x						( GAME_SCREEN_W2 ) 
#define k_about_pos_y						( GAME_SCREEN_H + k_about_line_spacing )

#define ABOUT_DEFAULT_FONT					( L"MM_Normal" ) 
#define ABOUT_DEFAULT_COLOR					( 0xFFFFFFFF )

